package org.springframework.samples.petclinic.owner;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.Statement;
import java.util.Map;

import io.restassured.http.ContentType;
import io.restassured.response.Response;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.empty;
import static org.hamcrest.Matchers.equalTo;

/**
 * Black-Box API Integration Test
 *
 * @target-controller OwnerRestController
 * (src/main/java/org/springframework/samples/petclinic/owner/OwnerRestController.java)
 * @target-api GET /api/owners/{ownerId} (handler: getOwner)
 *
 * No internal classes are imported; all verification happens through RestAssured HTTP
 * calls plus direct JDBC reads/writes against the real application database.
 *
 * NIMBUS trace: .nimbus/artifacts/test-plan/OwnerRestController_getOwner.md,
 * .nimbus/artifacts/vtc-plan/OwnerRestController_getOwner.md,
 * .nimbus/artifacts/analyze-auth-flow/api_owners_ownerId.json,
 * .nimbus/artifacts/detect-external-calls/OwnerRestController_getOwner.json
 * (external_calls: [] -> no WireMock stub needed for this endpoint).
 *
 * Deviations from the generic VTC template (documented, not silently dropped):
 * - ownerId is a required @PathVariable Integer, not a form/body param, so the generic
 * NULL/EMPTY form-field rules do not map 1:1 onto it. NULL is modeled as the path
 * variable segment being entirely absent (trailing slash -> no route match -> 404).
 * EMPTY is skipped: a path variable segment cannot be "present but empty" as a state
 * distinct from "absent" (PathPattern requires >=1 char to bind {ownerId} at all), so
 * there is no additional HTTP interaction EMPTY would exercise beyond NULL.
 * - The generic api-level VTCs (emptyBody/structureTamper/badHeader) assume a request
 * body, which a bodyless GET-by-path-variable endpoint does not have; overflow/xss are
 * covered instead by VTC_ownerId_LENGTH_EXCEEDED / VTC_ownerId_SPECIAL_CHAR, and
 * wrongMethod is covered by ATC_wrongMethod_returns405.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class ApiOwnersOwnerIdBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static final String API_PATH = "/api/owners/{ownerId}";

	private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/petclinic");

	private static final String DB_USER = System.getProperty("test.db.user", "petclinic");

	private static final String DB_PASSWORD = System.getProperty("test.db.password", "petclinic");

	private static final String AUTH_USERNAME = System.getProperty("test.auth.username", "user");

	private static final String AUTH_PASSWORD = System.getProperty("test.auth.password", "password");

	private static String authToken;

	@BeforeAll
	static void obtainAuthToken() {
		// Infra-only initialization (real /api/auth/login call) - no test data INSERT here.
		Response loginResponse = given().baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body("{\"username\":\"" + AUTH_USERNAME + "\",\"password\":\"" + AUTH_PASSWORD + "\"}")
		.when()
			.post("/api/auth/login");
		authToken = loginResponse.jsonPath().getString("token");
	}

	private static Connection getDbConnection() throws Exception {
		return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
	}

	/** Deterministic per-test-method id block (10 reserved slots) so parallel methods never collide. */
	private static final class TestIds {

		final String ownerWithPetsId;

		final String petAId;

		final String visit1Id;

		final String visit2Id;

		final String petBId;

		final String ownerNoPetsId;

		final String notFoundId;

		TestIds(long base) {
			this.ownerWithPetsId = String.valueOf(base);
			this.petAId = String.valueOf(base + 1);
			this.visit1Id = String.valueOf(base + 2);
			this.visit2Id = String.valueOf(base + 3);
			this.petBId = String.valueOf(base + 4);
			this.ownerNoPetsId = String.valueOf(base + 5);
			this.notFoundId = String.valueOf(base + 6);
		}

		Map<String, String> asParams() {
			return Map.of("OWNER_WITH_PETS_ID", ownerWithPetsId, "PET_A_ID", petAId, "VISIT_1_ID", visit1Id,
					"VISIT_2_ID", visit2Id, "PET_B_ID", petBId, "OWNER_NO_PETS_ID", ownerNoPetsId);
		}

	}

	private TestIds ids(TestInfo info) {
		long base = 91_000_000L + (long) (Math.abs(info.getTestMethod().get().getName().hashCode()) % 90_000) * 10L;
		return new TestIds(base);
	}

	private void setupData(TestIds ids) {
		executeSqlTemplate("sql/api-owners-owner-id-teardown.sql", ids.asParams());
		executeSqlTemplate("sql/api-owners-owner-id-setup.sql", ids.asParams());
	}

	private void teardownData(TestIds ids) {
		executeSqlTemplate("sql/api-owners-owner-id-teardown.sql", ids.asParams());
	}

	private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
		try (Connection conn = getDbConnection();
				InputStream is = ApiOwnersOwnerIdBlackBoxTest.class.getClassLoader().getResourceAsStream(resourcePath);
				Statement stmt = conn.createStatement()) {
			String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
			for (var entry : params.entrySet()) {
				sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
			}
			for (String line : sql.split("\n")) {
				String trimmed = line.trim();
				if (trimmed.startsWith("--") || trimmed.isEmpty()) {
					continue;
				}
				if (trimmed.endsWith(";")) {
					trimmed = trimmed.substring(0, trimmed.length() - 1);
				}
				if (!trimmed.isEmpty()) {
					stmt.execute(trimmed);
				}
			}
		}
		catch (Exception e) {
			throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
		}
	}

	// ------------------------------------------------------------------
	// NTC - Happy Path (maps to test-plan NTC_branch_getOwner_2 + boundary variations)
	// ------------------------------------------------------------------

	@Test
	@DisplayName("NTC_getOwner_withPetsAndVisits - owner with two pets, one with visits")
	void NTC_getOwner_withPetsAndVisits(TestInfo info) {
		TestIds ids = ids(info);
		setupData(ids);
		try {
			given().baseUri(BASE_URL)
				.header("Authorization", "Bearer " + authToken)
				.accept(ContentType.JSON)
			.when()
				.get(API_PATH, ids.ownerWithPetsId)
			.then().log().ifValidationFails()
				.statusCode(200)
				.contentType(ContentType.JSON)
				.body("id", equalTo(Integer.parseInt(ids.ownerWithPetsId)))
				.body("firstName", equalTo("NimbusOwner"))
				.body("lastName", equalTo("WithPets"))
				.body("address", equalTo("100 Nimbus Test St"))
				.body("city", equalTo("NimbusCity"))
				.body("telephone", equalTo("6085551111"))
				.body("pets.size()", equalTo(2))
				.body("pets[0].id", equalTo(Integer.parseInt(ids.petAId)))
				.body("pets[0].name", equalTo("NimbusCatA"))
				.body("pets[0].birthDate", equalTo("2015-05-20"))
				.body("pets[0].type.id", equalTo(1))
				.body("pets[0].type.name", equalTo("cat"))
				.body("pets[0].visits.size()", equalTo(2))
				.body("pets[0].visits[0].id", equalTo(Integer.parseInt(ids.visit1Id)))
				.body("pets[0].visits[0].date", equalTo("2020-01-15"))
				.body("pets[0].visits[0].description", equalTo("Nimbus annual checkup"))
				.body("pets[0].visits[1].id", equalTo(Integer.parseInt(ids.visit2Id)))
				.body("pets[0].visits[1].date", equalTo("2021-02-20"))
				.body("pets[0].visits[1].description", equalTo("Nimbus vaccination"))
				.body("pets[1].id", equalTo(Integer.parseInt(ids.petBId)))
				.body("pets[1].name", equalTo("NimbusDogB"));
		}
		finally {
			teardownData(ids);
		}
	}

	@Test
	@DisplayName("NTC_getOwner_noPets - owner with an empty pets array")
	void NTC_getOwner_noPets(TestInfo info) {
		TestIds ids = ids(info);
		setupData(ids);
		try {
			given().baseUri(BASE_URL)
				.header("Authorization", "Bearer " + authToken)
				.accept(ContentType.JSON)
			.when()
				.get(API_PATH, ids.ownerNoPetsId)
			.then().log().ifValidationFails()
				.statusCode(200)
				.contentType(ContentType.JSON)
				.body("id", equalTo(Integer.parseInt(ids.ownerNoPetsId)))
				.body("firstName", equalTo("NimbusOwner"))
				.body("lastName", equalTo("NoPets"))
				.body("address", equalTo("200 Nimbus Test Ave"))
				.body("city", equalTo("NimbusVille"))
				.body("telephone", equalTo("6085552222"))
				.body("pets", empty());
		}
		finally {
			teardownData(ids);
		}
	}

	@Test
	@DisplayName("NTC_getOwner_petWithoutVisits - boundary: a pet with an empty visits array")
	void NTC_getOwner_petWithoutVisits(TestInfo info) {
		TestIds ids = ids(info);
		setupData(ids);
		try {
			given().baseUri(BASE_URL)
				.header("Authorization", "Bearer " + authToken)
				.accept(ContentType.JSON)
			.when()
				.get(API_PATH, ids.ownerWithPetsId)
			.then().log().ifValidationFails()
				.statusCode(200)
				.body("pets.size()", equalTo(2))
				.body("pets[1].id", equalTo(Integer.parseInt(ids.petBId)))
				.body("pets[1].name", equalTo("NimbusDogB"))
				.body("pets[1].birthDate", equalTo("2018-08-08"))
				.body("pets[1].type.id", equalTo(2))
				.body("pets[1].type.name", equalTo("dog"))
				.body("pets[1].visits", empty());
		}
		finally {
			teardownData(ids);
		}
	}

	// ------------------------------------------------------------------
	// ATC - Business / infra exceptions
	// ------------------------------------------------------------------

	@Test
	@DisplayName("ATC_ownerId_notFound - valid numeric id with no matching row -> 404 (maps to ATC_ownerId_noData)")
	void ATC_ownerId_notFound(TestInfo info) {
		TestIds ids = ids(info);
		setupData(ids);
		try {
			given().baseUri(BASE_URL)
				.header("Authorization", "Bearer " + authToken)
				.accept(ContentType.JSON)
			.when()
				.get(API_PATH, ids.notFoundId)
			.then().log().ifValidationFails()
				.statusCode(404)
				.body(equalTo(""));
		}
		finally {
			teardownData(ids);
		}
	}

	@Test
	@DisplayName("ATC_ownerId_invalidFormat - non-numeric id -> 400 (maps to ATC_code400)")
	void ATC_ownerId_invalidFormat(TestInfo info) {
		TestIds ids = ids(info);
		setupData(ids);
		try {
			given().baseUri(BASE_URL)
				.header("Authorization", "Bearer " + authToken)
				.accept(ContentType.JSON)
			.when()
				.get(API_PATH, "abc")
			.then().log().ifValidationFails()
				.statusCode(400)
				.body("status", equalTo(400))
				.body("error", equalTo("Bad Request"));
		}
		finally {
			teardownData(ids);
		}
	}

	@Test
	@DisplayName("ATC_missingAuthHeader - no Authorization header -> 403 (Spring Security default entry point)")
	void ATC_missingAuthHeader(TestInfo info) {
		TestIds ids = ids(info);
		setupData(ids);
		try {
			given().baseUri(BASE_URL)
				.accept(ContentType.JSON)
			.when()
				.get(API_PATH, ids.ownerWithPetsId)
			.then().log().ifValidationFails()
				.statusCode(403);
		}
		finally {
			teardownData(ids);
		}
	}

	@Test
	@DisplayName("ATC_invalidAuthToken - malformed JWT -> 403")
	void ATC_invalidAuthToken(TestInfo info) {
		TestIds ids = ids(info);
		setupData(ids);
		try {
			given().baseUri(BASE_URL)
				.header("Authorization", "Bearer invalid.jwt.token")
				.accept(ContentType.JSON)
			.when()
				.get(API_PATH, ids.ownerWithPetsId)
			.then().log().ifValidationFails()
				.statusCode(403);
		}
		finally {
			teardownData(ids);
		}
	}

	@Test
	@DisplayName("ATC_wrongMethod_returns405 - DELETE is not mapped on this path -> 405 (maps to VTC_api_wrongMethod)")
	void ATC_wrongMethod_returns405(TestInfo info) {
		TestIds ids = ids(info);
		setupData(ids);
		try {
			given().baseUri(BASE_URL)
				.header("Authorization", "Bearer " + authToken)
				.accept(ContentType.JSON)
			.when()
				.delete(API_PATH, ids.ownerWithPetsId)
			.then().log().ifValidationFails()
				.statusCode(405);
		}
		finally {
			teardownData(ids);
		}
	}

	// ------------------------------------------------------------------
	// VTC - ownerId mutations (VTC standard rules adapted for a required @PathVariable Integer)
	// ------------------------------------------------------------------

	@Test
	@DisplayName("VTC_ownerId_NULL - path variable segment entirely absent -> 404 (no route match)")
	void VTC_ownerId_NULL(TestInfo info) {
		TestIds ids = ids(info);
		setupData(ids);
		try {
			given().baseUri(BASE_URL)
				.header("Authorization", "Bearer " + authToken)
				.accept(ContentType.JSON)
			.when()
				.get("/api/owners/")
			.then().log().ifValidationFails()
				.statusCode(404);
		}
		finally {
			teardownData(ids);
		}
	}

	@Test
	@DisplayName("VTC_ownerId_WHITE_SPACE - whitespace-only id -> 400 (conversion failure)")
	void VTC_ownerId_WHITE_SPACE(TestInfo info) {
		TestIds ids = ids(info);
		setupData(ids);
		try {
			given().baseUri(BASE_URL)
				.header("Authorization", "Bearer " + authToken)
				.accept(ContentType.JSON)
			.when()
				.get(API_PATH, " ")
			.then().log().ifValidationFails()
				.statusCode(400)
				.body("status", equalTo(400));
		}
		finally {
			teardownData(ids);
		}
	}

	@Test
	@DisplayName("VTC_ownerId_SPECIAL_CHAR - SQL-injection-shaped id -> 400 (rejected by type conversion before any DB query)")
	void VTC_ownerId_SPECIAL_CHAR(TestInfo info) {
		TestIds ids = ids(info);
		setupData(ids);
		try {
			given().baseUri(BASE_URL)
				.header("Authorization", "Bearer " + authToken)
				.accept(ContentType.JSON)
			.when()
				.get(API_PATH, "1' OR '1'='1")
			.then().log().ifValidationFails()
				.statusCode(400)
				.body("status", equalTo(400));
		}
		finally {
			teardownData(ids);
		}
	}

	@Test
	@DisplayName("VTC_ownerId_INVALID_FORMAT - decimal id -> 400 (not a valid Integer)")
	void VTC_ownerId_INVALID_FORMAT(TestInfo info) {
		TestIds ids = ids(info);
		setupData(ids);
		try {
			given().baseUri(BASE_URL)
				.header("Authorization", "Bearer " + authToken)
				.accept(ContentType.JSON)
			.when()
				.get(API_PATH, "12.5")
			.then().log().ifValidationFails()
				.statusCode(400)
				.body("status", equalTo(400));
		}
		finally {
			teardownData(ids);
		}
	}

	@Test
	@DisplayName("VTC_ownerId_LENGTH_EXCEEDED - id exceeds Integer range -> 400 (numeric overflow; maps to VTC_api_overflow)")
	void VTC_ownerId_LENGTH_EXCEEDED(TestInfo info) {
		TestIds ids = ids(info);
		setupData(ids);
		try {
			given().baseUri(BASE_URL)
				.header("Authorization", "Bearer " + authToken)
				.accept(ContentType.JSON)
			.when()
				.get(API_PATH, "99999999999999")
			.then().log().ifValidationFails()
				.statusCode(400)
				.body("status", equalTo(400));
		}
		finally {
			teardownData(ids);
		}
	}

}

