		authToken = loginResponse.jsonPath().getString("token");
	}

	private static Connection getDbConnection() throws Exception {
		return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
	}

	/** Deterministic per-test-method id block (10 reserved slots) so parallel methods never collide. */
	private static final class TestIds {

		final String ownerWithPetsId;

		final String petAId;

		final String visit1Id;

		final String visit2Id;

		final String petBId;

		final String ownerNoPetsId;

		final String notFoundId;

		TestIds(long base) {
			this.ownerWithPetsId = String.valueOf(base);
			this.petAId = String.valueOf(base + 1);
			this.visit1Id = String.valueOf(base + 2);
			this.visit2Id = String.valueOf(base + 3);
			this.petBId = String.valueOf(base + 4);
			this.ownerNoPetsId = String.valueOf(base + 5);
			this.notFoundId = String.valueOf(base + 6);
		}

		Map<String, String> asParams() {
			return Map.of("OWNER_WITH_PETS_ID", ownerWithPetsId, "PET_A_ID", petAId, "VISIT_1_ID", visit1Id,
					"VISIT_2_ID", visit2Id, "PET_B_ID", petBId, "OWNER_NO_PETS_ID", ownerNoPetsId);
		}

	}

	private TestIds ids(TestInfo info) {
		long base = 91_000_000L + (long) (Math.abs(info.getTestMethod().get().getName().hashCode()) % 90_000) * 10L;
		return new TestIds(base);
	}

	private void setupData(TestIds ids) {
		executeSqlTemplate("sql/api-owners-owner-id-teardown.sql", ids.asParams());
		executeSqlTemplate("sql/api-owners-owner-id-setup.sql", ids.asParams());
	}

	private void teardownData(TestIds ids) {
		executeSqlTemplate("sql/api-owners-owner-id-teardown.sql", ids.asParams());
	}

	private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
		try (Connection conn = getDbConnection();
				InputStream is = ApiOwnersOwnerIdBlackBoxTest.class.getClassLoader().getResourceAsStream(resourcePath);
				Statement stmt = conn.createStatement()) {
			String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
			for (var entry : params.entrySet()) {
				sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
			}
			for (String line : sql.split("\n")) {
				String trimmed = line.trim();
				if (trimmed.startsWith("--") || trimmed.isEmpty()) {
					continue;
				}
				if (trimmed.endsWith(";")) {
					trimmed = trimmed.substring(0, trimmed.length() - 1);
				}
				if (!trimmed.isEmpty()) {
					stmt.execute(trimmed);
				}
			}
		}
		catch (Exception e) {
			throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
		}
	}

